// DeleteOne permanently deletes a single RecipeCommit record by ID
func (r *RecipeCommitRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	query := `DELETE FROM recipe_commit WHERE id = $1`

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, id.ToUUID())
	} else {
		result, err = r.db.pool.Exec(ctx, query, id.ToUUID())
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

